-- Destinatário em Rondônia (cidade Seringueiras)

-- Empresa mínima, criada só se não existir nenhuma (o sistema espera uma única empresa)
update empresa_parametros set serie_nfe = 1 where (serie_nfe is null or serie_nfe = 0) and codigo in (select parametro_codigo from empresa);
update empresa_parametros set tipo_ambiente_codigo = 2 where tipo_ambiente_codigo is null and codigo in (select parametro_codigo from empresa);

-- Tributações: 9101 com regra de saída para RO, 9102 só com regra de entrada, 9103 com regra de saída só para SP


